"""Desktop entry loading, command expansion, and application launch."""
import os
import subprocess
from errors import io_fail, unwrap_none
from ini_data import read_ini, IniError
from mimes import parse_mime, MimeError


class DesktopError(ValueError):
    pass


def shell_words(text):
    """Split shell-style words without variable, tilde, or glob expansion."""
    words = []
    word = []
    active = False
    quoted = None
    i = 0
    while i < len(text):
        c = text[i]
        if quoted == "'":
            if c == "'":
                quoted = None
            else:
                word.append(c)
            i += 1
            continue
        if quoted == '"':
            if c == '"':
                quoted = None
                i += 1
                continue
            if c == '\\':
                if i + 1 == len(text):
                    return None
                nxt = text[i+1]
                if nxt in ('$', '`', '"', '\\', '\n'):
                    if nxt != '\n':
                        word.append(nxt)
                    i += 2
                    continue
            word.append(c)
            i += 1
            continue
        if c in ' \t\r\n':
            if active:
                words.append(''.join(word))
                word = []
                active = False
            i += 1
        elif c == '#' and not active:
            end = text.find('\n', i)
            if end == -1:
                i = len(text)
            else:
                i = end + 1
        elif c in "'\"":
            quoted = c
            active = True
            i += 1
        elif c == '\\':
            if i + 1 == len(text):
                return None
            nxt = text[i+1]
            if nxt != '\n':
                word.append(nxt)
                active = True
            i += 2
        else:
            word.append(c)
            active = True
            i += 1
    if quoted:
        return None
    if active:
        words.append(''.join(word))
    return words


class DesktopEntry:
    def __init__(self, identifier, path, data):
        self.id = identifier
        self.path = path
        self.name = data['Name']
        self.exec = data['Exec']
        self.terminal = data.get('Terminal') == 'true'
        self.mimes = []
        for value in data.get('MimeType', '').split(';'):
            try:
                mime = parse_mime(value)
                if mime not in self.mimes:
                    self.mimes.append(mime)
            except MimeError:
                pass

    def command(self, args, terminal=True):
        words = shell_words(self.exec)
        if words is None:
            unwrap_none('src/common/desktop_entry.rs:65:49')
        if not words:
            unwrap_none('src/common/desktop_entry.rs:66:43')
        cmd = []
        replaced = False
        for word in words:
            if word in ('%f', '%F', '%u', '%U'):
                cmd.extend(args)
                replaced = True
            else:
                for marker in ('%f', '%F', '%u', '%U'):
                    if marker in word:
                        word = word.replace(marker, ' '.join(args))
                        replaced = True
                cmd.append(word)
        if not replaced:
            cmd.extend(args)
        if not cmd:
            unwrap_none('src/common/desktop_entry.rs:66:43')
        if self.terminal and terminal:
            # A terminal is resolved separately; without one the command
            # cannot be materialized, even for the JSON representation.
            io_fail()
        return cmd

    def json_command(self):
        cmd = self.command([])
        return cmd[0] + ' ' + ' '.join(cmd[1:])

    def launch(self, args):
        cmd = self.command(args)
        try:
            subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL, start_new_session=True)
        except OSError as ex:
            io_fail(ex)
        except ValueError:
            io_fail(OSError(22, 'Invalid argument'))


def read_desktop(identifier, path):
    try:
        with open(path, encoding='utf-8') as file:
            data = read_ini(file.read()).get('Desktop Entry', {})
        if not data.get('Name') or not data.get('Exec'):
            raise DesktopError('malformed desktop entry at ' + path)
        return DesktopEntry(identifier, path, data)
    except (OSError, UnicodeError, IniError):
        raise DesktopError('malformed desktop entry at ' + path)


class DesktopStore:
    def __init__(self, env):
        self.env = env
        self.entries = {}
        self.system = None

    def find(self, identifier):
        if identifier in self.entries:
            return self.entries[identifier]
        for directory in self.env.app_dirs:
            path = os.path.join(directory, identifier)
            if os.path.isfile(path):
                entry = read_desktop(identifier, path)
                self.entries[identifier] = entry
                return entry
        raise DesktopError("no handlers found for '%s'" % identifier)

    def associations(self):
        if self.system is not None:
            return self.system
        self.system = {}
        seen = set()
        for directory in self.env.app_dirs:
            try:
                items = list(os.scandir(directory))
            except OSError:
                continue
            for item in items:
                if not item.name.endswith('.desktop') or item.name in seen:
                    continue
                seen.add(item.name)
                try:
                    if not item.is_file():
                        continue
                    entry = self.find(item.name)
                except (DesktopError, OSError):
                    continue
                for mime in entry.mimes:
                    group = self.system.setdefault(mime, [])
                    if entry.id not in group:
                        group.append(entry.id)
        return self.system
