"""Association precedence and canonical mimeapps.list serialization."""
import os
import subprocess
import unicodedata
from pathlib import Path
from errors import io_debug, io_fail, unwrap_error, unwrap_none
from ini_data import read_ini, IniError
from mimes import parse_mime, MimeError
from desktop import DesktopError, shell_words


class Associations:
    def __init__(self, env, desktops):
        self.env = env
        self.desktops = desktops
        try:
            path = Path(env.mime_file)
            if not path.exists():
                path.parent.mkdir(parents=True, exist_ok=True)
                path.touch()
            text = path.read_text()
            data = read_ini(text)
        except IniError as ex:
            unwrap_error('src/apps/user.rs:12:65', 'ParseApps(' + ex.debug() + ')')
        except OSError as ex:
            unwrap_error('src/apps/user.rs:12:65', io_debug(ex))
        except UnicodeError:
            unwrap_error('src/apps/user.rs:12:65', 'Io(Custom { kind: InvalidData, error: "stream did not contain valid UTF-8" })')
        self.defaults = self._clean(data.get('Default Applications', {}))
        self.added = self._clean(data.get('Added Associations', {}))

    def _clean(self, data):
        result = {}
        for key, value in data.items():
            try:
                mime = parse_mime(key)
            except MimeError:
                continue
            ids = []
            for item in value.split(';'):
                if not item or item in ids:
                    continue
                try:
                    self.desktops.find(item)
                except DesktopError:
                    continue
                ids.append(item)
            if ids:
                result[mime] = ids
        return result

    def save(self):
        sections = []
        for title, data in [('Added Associations', self.added), ('Default Applications', self.defaults)]:
            lines = ['[' + title + ']']
            for mime in sorted(data):
                lines.append(mime + '=' + ';'.join(data[mime]) + ';')
            sections.append('\n'.join(lines) + '\n')
        try:
            Path(self.env.mime_file).write_text('\n'.join(sections))
        except OSError as ex:
            io_fail(ex)

    def change(self, command, mime, handler=None):
        if command == 'unset':
            if mime not in self.defaults:
                return
            del self.defaults[mime]
        elif command == 'add':
            self.defaults.setdefault(mime, []).append(handler)
        else:
            self.defaults[mime] = [handler]
        self.save()

    def _pick(self, entries):
        if not entries:
            return None
        if not self.env.enable_selector or len(entries) == 1:
            return self.desktops.find(entries[0])
        names = [self.desktops.find(item).name for item in entries]
        cmd = shell_words(self.env.selector)
        if not cmd:
            return None
        try:
            result = subprocess.run(cmd, input=('\n'.join(names) + '\n').encode(),
                                    stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
        except (OSError, ValueError):
            return None
        if result.returncode != 0:
            return None
        name = result.stdout.decode('utf-8', errors='replace').strip()
        if not name:
            return None
        if name not in names:
            unwrap_none('src/apps/user.rs:67:26')
        return self.desktops.find(entries[names.index(name)])

    def get(self, mime):
        exact = self._pick(self.defaults.get(mime, []))
        if exact:
            return exact
        wildcard = mime.split('/', 1)[0] + '/*'
        if wildcard != mime:
            chosen = self._pick(self.defaults.get(wildcard, []))
            if chosen:
                return chosen
        for mapping in [self.added, self.desktops.associations()]:
            if mime in mapping:
                return self.desktops.find(mapping[mime][0])
        io_fail()


def display_width(text):
    width = 0
    for c in text:
        if unicodedata.combining(c) or unicodedata.category(c) in ('Cc', 'Cf'):
            continue
        width += 2 if unicodedata.east_asian_width(c) in ('F', 'W') else 1
    return width


def clip(text, width):
    if display_width(text) <= width:
        return text + ' ' * (width - display_width(text))
    out = ''
    for c in text:
        if display_width(out + c) > width - 1:
            break
        out += c
    return out + '+' + ' ' * max(0, width - display_width(out) - 1)


def table(data):
    if not data:
        return '┌──┐\n│  │\n└──┘\n'
    rows = [(mime, ', '.join(data[mime])) for mime in sorted(data)]
    widths = [max(display_width(row[i]) for row in rows) for i in (0, 1)]
    while sum(widths) > 73:
        biggest = 0 if widths[0] > widths[1] else 1
        widths[biggest] -= 1
    top = '┌' + '┬'.join('─' * (w + 2) for w in widths) + '┐\n'
    middle = ''.join('│ ' + ' │ '.join(clip(row[i], widths[i]) for i in (0, 1)) + ' │\n' for row in rows)
    bottom = '└' + '┴'.join('─' * (w + 2) for w in widths) + '┘\n'
    return top + middle + bottom
