def shell_words(text):
    """Split shell-style words without variable, tilde, or glob expansion."""
    words = []
    word = []
    active = False
    quoted = None
    i = 0
    while i < len(text):
        c = text[i]
        if quoted == "'":
            if c == "'":
                quoted = None
            else:
                word.append(c)
            i += 1
            continue
        if quoted == '"':
            if c == '"':
                quoted = None
                i += 1
                continue
            if c == '\\':
                if i + 1 == len(text):
                    return None
                nxt = text[i+1]
                if nxt in ('$', '`', '"', '\\', '\n'):
                    if nxt != '\n':
                        word.append(nxt)
                    i += 2
                    continue
            word.append(c)
            i += 1
            continue
        if c in ' \t\r\n':
            if active:
                words.append(''.join(word))
                word = []
                active = False
            i += 1
        elif c == '#' and not active:
            end = text.find('\n', i)
            if end == -1:
                i = len(text)
            else:
                i = end + 1
        elif c in "'\"":
            quoted = c
            active = True
            i += 1
        elif c == '\\':
            if i + 1 == len(text):
                return None
            nxt = text[i+1]
            if nxt != '\n':
                word.append(nxt)
                active = True
            i += 2
        else:
            word.append(c)
            active = True
            i += 1
    if quoted:
        return None
    if active:
        words.append(''.join(word))
    return words


