"""Input paths and URL normalization for the open command."""
import os
import re
import urllib.parse
from errors import io_fail


class PathError(ValueError):
    pass


_SPECIAL = {'http': 80, 'https': 443, 'ftp': 21, 'ws': 80, 'wss': 443}


def url_escape(value, kind='path'):
    safe = "/!$&'()*+,-.:;=@_~%[]|" if kind == 'path' else "/?!$&'()*+,-.:;=@_~%[]|\\^`{}"
    if kind == 'fragment':
        safe += '#'
    return urllib.parse.quote(value, safe=safe)


def normalized_segments(path):
    output = []
    segments = path.split('/')
    for i, segment in enumerate(segments):
        dot = re.sub('%2[6-8].*', lambda m: m[0], segment) if False else segment.lower().replace('%2b', '%2b')
        dot = re.sub(r'%2e', '.', segment, flags=re.I)
        if dot == '.':
            if i == len(segments) - 1:
                output.append('')
        elif dot == '..':
            if output and not (len(output) == 1 and output[0] == ''):
                output.pop()
            if i == len(segments) - 1:
                output.append('')
        else:
            output.append(segment)
    result = '/'.join(output)
    if path.startswith('/') and not result.startswith('/'):
        result = '/' + result
    return result


def parse_url(value):
    """Return (normalized value, scheme), or None for a filesystem input."""
    text = value.strip(''.join(chr(i) for i in range(33)))
    text = text.replace('\t', '').replace('\r', '').replace('\n', '')
    match = re.match(r'^([A-Za-z][A-Za-z0-9+.-]*):', text)
    if not match:
        return None
    scheme = match[1].lower()
    tail = text[match.end():]
    if scheme in _SPECIAL:
        rest = tail.replace('\\', '/')
        rest = rest.lstrip('/')
        candidate = scheme + '://' + rest
        try:
            parsed = urllib.parse.urlsplit(candidate)
            hostname = parsed.hostname
            if not hostname or any(c in hostname for c in ' <>#?\\^|%\x00'):
                return None
            port = parsed.port
            hostname = hostname.encode('idna').decode('ascii').lower()
            if ':' in hostname:
                hostname = '[' + hostname.strip('[]') + ']'
            auth = ''
            if '@' in parsed.netloc:
                raw_auth = parsed.netloc.rsplit('@', 1)[0]
                auth = urllib.parse.quote(raw_auth, safe=":!$&'()*+,-._~%=") + '@'
            authority = auth + hostname
            if port is not None and port != _SPECIAL[scheme]:
                authority += ':' + str(port)
            path = normalized_segments(parsed.path or '/')
            result = scheme + '://' + authority + url_escape(path)
            before_hash = candidate.split('#', 1)[0]
            if '?' in before_hash:
                result += '?' + url_escape(parsed.query, 'query')
            if '#' in candidate:
                result += '#' + url_escape(parsed.fragment, 'fragment')
            return result, scheme
        except (ValueError, UnicodeError):
            return None
    if scheme == 'file':
        rest = tail.replace('\\', '/')
        if not rest.startswith('//'):
            rest = '//' + ('/' if not rest.startswith('/') else '') + rest
        try:
            parsed = urllib.parse.urlsplit('file:' + rest)
            if parsed.port is not None or '@' in parsed.netloc:
                return None
            path = normalized_segments(parsed.path or '/')
            encoded_path = url_escape(path)
            if parsed.hostname and parsed.hostname.lower() != 'localhost':
                raise PathError('Bad path: ' + encoded_path)
            try:
                path = urllib.parse.unquote_to_bytes(encoded_path).decode('utf-8')
            except UnicodeError:
                raise PathError('Bad path: ' + encoded_path)
            return path, None
        except ValueError as ex:
            if isinstance(ex, PathError):
                raise
            return None
    try:
        parsed = urllib.parse.urlsplit(scheme + ':' + tail)
    except ValueError:
        return None
    # Non-special schemes preserve their opaque path rather than requiring a
    # hostname.  Only non-ASCII characters and control characters are escaped.
    result = scheme + ':'
    if tail.startswith('//'):
        result += '//' + parsed.netloc
        path = normalized_segments(parsed.path)
        result += url_escape(path)
    else:
        result += urllib.parse.quote(parsed.path, safe=" /!$&'()*+,-.:;=@_~%[]|\\^`{}<>")
    if '?' in tail.split('#', 1)[0]:
        result += '?' + url_escape(parsed.query, 'query')
    if '#' in tail:
        result += '#' + url_escape(parsed.fragment, 'fragment')
    return result, scheme


class InputPath:
    def __init__(self, value):
        parsed = parse_url(value)
        if parsed is None:
            self.value = value
            self.scheme = None
        else:
