    'unset': ['<mime>'], 'launch': ['<mime>', '<args>...'],
    'get': ['<mime>'], 'add': ['<mime>', '<handler>'],
}
HELP_FLAGS = '    -h, --help       Prints help information\n    -V, --version    Prints version information\n'
FOOTER = 'For more information try --help\n'


def jaro_winkler(s, t):
    if s == t:
        return 1.0
    if not s or not t:
        return 0.0
    distance = max(len(s), len(t)) // 2 - 1
    distance = max(distance, 0)
    matched_s = [False] * len(s)
    matched_t = [False] * len(t)
    matches = 0
    for i, char in enumerate(s):
        for j in range(max(0, i-distance), min(len(t), i+distance+1)):
            if not matched_t[j] and t[j] == char:
                matched_s[i] = True
                matched_t[j] = True
                matches += 1
                break
    if not matches:
        return 0.0
    one = [s[i] for i in range(len(s)) if matched_s[i]]
    two = [t[i] for i in range(len(t)) if matched_t[i]]
    transpositions = sum(a != b for a, b in zip(one, two)) / 2
    jaro = (matches / len(s) + matches / len(t) + (matches-transpositions)/matches) / 3
    if jaro > 0.7:
        common = 0
        for a, b in zip(s[:4], t[:4]):
            if a != b:
                break
            common += 1
        jaro += common * .1 * (1-jaro)
    return jaro


def suggestion(value, choices):
    best, score = None, .8
    for item in choices:
        similarity = jaro_winkler(value, item)
        if similarity > score:
            best, score = item, similarity
    return best


class CLI:
    def __init__(self, argv, db, desktops):
        self.name = os.path.basename(argv[0]) or 'executable'
        self.argv = argv[1:]
        self.db = db
