"""Command-line grammar, help pages, and usage diagnostics."""
import os
from errors import Failure
from mimes import MimeError
from desktop import DesktopError
from input_paths import InputPath, PathError

DESCRIPTIONS = {
    'list': 'List default apps and the associated handlers',
    'open': 'Open a path/URL with its default handler',
    'set': 'Set the default handler for mime/extension',
    'unset': 'Unset the default handler for mime/extension',
    'launch': 'Launch the handler for specified extension/mime with optional arguments',
    'get': 'Get handler for this mime/extension',
    'add': 'Add a handler for given mime/extension Note that the first handler is the default',
}
TAILS = {
    'list': '[FLAGS]', 'open': '<paths>...', 'set': '<mime> <handler>',
    'unset': '<mime>', 'launch': '<mime> [args]...', 'get': '[FLAGS] <mime>',
    'add': '<mime> <handler>',
}
ARGUMENTS = {
    'list': [], 'open': ['<paths>...'], 'set': ['<mime>', '<handler>'],
    'unset': ['<mime>'], 'launch': ['<mime>', '<args>...'],
    'get': ['<mime>'], 'add': ['<mime>', '<handler>'],
}
HELP_FLAGS = '    -h, --help       Prints help information\n    -V, --version    Prints version information\n'
FOOTER = 'For more information try --help\n'


def jaro_winkler(s, t):
    if s == t:
        return 1.0
    if not s or not t:
        return 0.0
    distance = max(len(s), len(t)) // 2 - 1
    distance = max(distance, 0)
    matched_s = [False] * len(s)
    matched_t = [False] * len(t)
    matches = 0
    for i, char in enumerate(s):
        for j in range(max(0, i-distance), min(len(t), i+distance+1)):
            if not matched_t[j] and t[j] == char:
                matched_s[i] = True
                matched_t[j] = True
                matches += 1
                break
    if not matches:
        return 0.0
    one = [s[i] for i in range(len(s)) if matched_s[i]]
    two = [t[i] for i in range(len(t)) if matched_t[i]]
    transpositions = sum(a != b for a, b in zip(one, two)) / 2
    jaro = (matches / len(s) + matches / len(t) + (matches-transpositions)/matches) / 3
    if jaro > 0.7:
        common = 0
        for a, b in zip(s[:4], t[:4]):
            if a != b:
                break
            common += 1
        jaro += common * .1 * (1-jaro)
    return jaro


def suggestion(value, choices):
    best, score = None, .8
    for item in choices:
        similarity = jaro_winkler(value, item)
        if similarity > score:
            best, score = item, similarity
    return best


class CLI:
    def __init__(self, argv, db, desktops):
        self.name = os.path.basename(argv[0]) or 'executable'
        self.argv = argv[1:]
        self.db = db
        self.desktops = desktops
        self.command = None
        self.flags = set()
        self.values = []
        self.mime = None
        self.handler = None
        self.paths = []
        self.args = []

    def usage(self, extra=None):
        if self.command is None:
            return self.name + ' <SUBCOMMAND>'
        if extra is not None:
            parts = [self.name, self.command]
            if self.command not in ('list', 'open'):
                parts += ['<mime>']
                if self.command in ('set', 'add'):
                    parts.append('<handler>')
            elif self.command == 'open':
                parts.append('<paths>...')
            parts += ['--' + f for f in self.flags if f != extra]
            parts.append('--' + extra)
            return ' '.join(parts)
        return self.name + ' ' + self.command + ' ' + TAILS[self.command]

    def help(self):
        if not self.command:
            return ('handlr 0.6.4\n\nUSAGE:\n    ' + self.usage() + '\n\nFLAGS:\n' + HELP_FLAGS +
                    '\nSUBCOMMANDS:\n' + ''.join('    ' + sub.ljust(10) + desc + '\n' for sub, desc in DESCRIPTIONS.items()))
        text = self.name + '-' + self.command + ' \n' + DESCRIPTIONS[self.command]
        text += '\n\nUSAGE:\n    ' + self.usage() + '\n'
        args = ARGUMENTS[self.command]
        if args:
            width = max(len(arg) for arg in args) + 4
            text += '\nARGS:\n' + ''.join('    ' + arg.ljust(width) + '\n' for arg in args)
        text += '\nFLAGS:\n'
        if self.command == 'list':
            text += '    -a, --all        \n'
        if self.command == 'get':
            text += '        --json       \n'
        return text + HELP_FLAGS

    def output(self, text, code=0, stdout=True):
        raise Failure(text, code, stdout)

    def error(self, text, usage=True):
        body = 'error: ' + text + '\n\n'
        if usage:
            body += 'USAGE:\n    ' + self.usage() + '\n\n'
        raise Failure(body + FOOTER, 2)

    def invalid(self, argument, error):
        self.error("Invalid value for '%s': %s" % (argument, error), False)

    def unexpected(self, value, after_double_dash=False):
        hint = None
        if self.command is None and not value.startswith('-') and not after_double_dash:
            hint = suggestion(value, DESCRIPTIONS)
            if hint:
                self.error("The subcommand '%s' wasn't recognized\n\n\tDid you mean '%s'?\n\n"
                           "If you believe you received this message in error, try re-running with '%s -- %s'"
                           % (value, hint, self.name, value))
        if value.startswith('--') and not after_double_dash:
            candidates = ['help', 'version']
            if self.command == 'list':
                candidates.append('all')
            if self.command == 'get':
                candidates.append('json')
            hint = suggestion(value[2:], candidates)
        text = "error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\n" % value
        if hint:
            text += "\tDid you mean '--%s'?\n\n" % hint
        text += 'If you tried to supply `%s` as a PATTERN use `-- %s`\n\n' % (value, value)
        text += 'USAGE:\n    ' + self.usage(hint) + '\n\n' + FOOTER
        raise Failure(text, 2)

    def flag(self, flag):
        if flag == 'help':
            self.output(self.help())
        if flag == 'version':
            self.output((self.name + '-' + self.command + ' \n') if self.command else 'handlr 0.6.4\n')
        if flag in self.flags:
            self.error("The argument '--%s' was provided more than once, but cannot be used multiple times" % flag)
        self.flags.add(flag)

    def parse(self):
        options = True
        for value in self.argv:
            if options and value == '--':
                options = False
                continue
            if options and value.startswith('--'):
                long = value[2:].split('=', 1)[0]
                if long in ('help', 'version') or self.command == 'list' and long == 'all' or self.command == 'get' and long == 'json':
                    self.flag(long)
                else:
                    self.unexpected(value)
                continue
            if options and len(value) > 1 and value.startswith('-'):
                for short in value[1:]:
                    if short == 'h':
                        self.flag('help')
                    elif short == 'V':
                        self.flag('version')
                    elif short == 'a' and self.command == 'list':
                        self.flag('all')
                    else:
                        self.unexpected('-' + short)
                continue
            if self.command is None:
                if value in DESCRIPTIONS and options:
                    self.command = value
                else:
                    self.unexpected(value, not options)
                continue
            maxargs = {'list': 0, 'get': 1, 'unset': 1, 'set': 2, 'add': 2}.get(self.command)
            if maxargs is not None and len(self.values) >= maxargs:
                self.unexpected(value, not options)
            self.values.append(value)
        if self.command is None:
            self.output(self.help(), 2, False)
        required = {'list': 0, 'set': 2, 'add': 2}.get(self.command, 1)
        if len(self.values) < required:
            names = ARGUMENTS[self.command][len(self.values):required]
            self.error('The following required arguments were not provided:\n' + '\n'.join('    ' + arg for arg in names))
        for i, value in enumerate(self.values):
            argument = ARGUMENTS[self.command][min(i, len(ARGUMENTS[self.command])-1)]
            if not value:
                self.error("The argument '%s' requires a value but none was supplied" % argument)
            try:
                if argument == '<mime>':
                    self.mime = self.db.argument(value)
                elif argument == '<handler>':
                    self.handler = self.desktops.find(value).id
                elif argument == '<paths>...':
                    self.paths.append(InputPath(value))
                else:
                    self.args.append(value)
            except (MimeError, DesktopError, PathError) as ex:
                self.invalid(argument, str(ex))
        return self
