"""Reader and matcher for the binary shared MIME-info magic file format."""
import os
import re
from mimes import parse_mime, MimeError


class Rule:
    def __init__(self, offset, value, mask, distance):
        self.offset = offset
        self.value = value
        self.mask = mask
        self.distance = distance
        self.children = []

    def matches(self, data):
        size = len(self.value)
        matched = False
        for offset in range(self.offset, self.offset + self.distance):
            if offset + size > len(data):
                break
            chunk = data[offset:offset+size]
            if self.mask is None:
                equal = chunk == self.value
            else:
                equal = all((a & mask) == (b & mask)
                            for a, b, mask in zip(chunk, self.value, self.mask))
            if equal:
                matched = True
                break
        return matched and (not self.children or any(child.matches(data) for child in self.children))


class MagicDatabase:
    def __init__(self, directories):
        self.records = []
        self.extent = 0
        for directory in directories:
            try:
                with open(os.path.join(directory, 'mime', 'magic'), 'rb') as f:
                    self._read(f.read())
            except OSError:
                pass

    def _read(self, data):
        header = b'MIME-Magic\x00\n'
        if not data.startswith(header):
            return
        pos = len(header)
        group = None
        stack = []
        while pos < len(data):
            if data[pos:pos+1] == b'[':
                end = data.find(b'\n', pos)
                if end < 0:
                    break
                line = data[pos:end]
                match = re.fullmatch(rb'\[\d+:([^\]]+)\]', line)
                group = None
                stack = []
                if match:
                    try:
                        mime = parse_mime(match[1].decode('utf-8'))
                        group = []
                        self.records.append((mime, group))
                    except (UnicodeError, MimeError):
                        pass
                pos = end + 1
                continue
            match = re.match(rb'(\d*)>(\d+)=', data[pos:])
            if not match:
                end = data.find(b'\n', pos)
                if end < 0:
                    break
                pos = end + 1
                continue
            depth = int(match[1] or b'0')
            offset = int(match[2])
            pos += match.end()
            if pos + 2 > len(data):
                break
            size = int.from_bytes(data[pos:pos+2], 'big')
            pos += 2
            if pos + size > len(data):
                break
            value = data[pos:pos+size]
            pos += size
            mask = None
            if data[pos:pos+1] == b'&':
                pos += 1
                if pos + size > len(data):
                    break
                mask = data[pos:pos+size]
                pos += size
            distance = 1
            while data[pos:pos+1] in (b'~', b'+'):
                operator = data[pos:pos+1]
                pos += 1
                number = re.match(rb'\d+', data[pos:])
                if not number:
                    break
                pos += number.end()
                if operator == b'+':
                    distance = int(number[0])
            end = data.find(b'\n', pos)
            pos = end + 1 if end >= 0 else len(data)
            if group is None or not size or distance < 1:
                continue
            rule = Rule(offset, value, mask, distance)
            self.extent = max(self.extent, offset + size + distance - 1)
            if depth == 0:
                group.append(rule)
                stack = [rule]
            elif depth <= len(stack):
                stack[depth-1].children.append(rule)
                stack = stack[:depth] + [rule]

    def file_type(self, path):
        buffer = b''
        if self.extent:
            try:
                with open(path, 'rb') as f:
                    buffer = f.read(self.extent)
            except (OSError, ValueError):
